gyR(){return"\u0645\u0646\u0627\u0637\u0642 \u0622\u0645\u0646\u0629 \u0645\u062d\u062f\u062f\u0629"},
gyP(){return"\u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u0628\u0627\u0644\u0645\u0646\u0627\u0637\u0642 \u0627\u0644\u0622\u0645\u0646\u0629"},
gyK(){return"\u0627\u0644\u0633\u0645\u0627\u062d \xab\u062f\u0627\u0626\u0645\u064b\u0627\xbb"},
gyI(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u062d\u0645\u0627\u064a\u0629"},
gz7(){return"\u0627\u062e\u062a\u0628\u0631 \u0627\u0644\u0622\u0646"},
gz9(){return"\u062c\u0627\u0631\u064d \u0642\u064a\u0627\u0633 \u0645\u0648\u0642\u0639\u0643\u2026"},
gpU(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0645\u0648\u0642\u0639 \u2014 GPS \u0645\u0637\u0641\u0623 \u0623\u0648 \u062f\u0627\u062e\u0644 \u0645\u0628\u0646\u0649 \u0623\u0648 \u0627\u0644\u0625\u0630\u0646 \u0645\u0641\u0642\u0648\u062f."},
