Hw(a){return"\u0627\u0637\u0644\u0639 "+a+" \u0639\u0644\u0649 \u0627\u0644\u062e\u062a\u0645 GPS"},
Hx(a){return"\u0627\u0637\u0644\u0639 "+a+" \u0639\u0644\u0649 \u062e\u062a\u0645 \u0627\u0644\u0635\u0648\u0631"},
HB(a){return"\u0646\u0632\u0651\u0644 "+a+" \u0639\u0646\u0635\u0631\u064b\u0627 \u0645\u0646 \u0627\u0644\u062e\u062a\u0645"},
Hs(a){return"\u0635\u062f\u0651\u0631 "+a+" \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a"},
