gAH(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d \u0645\u0648\u062b\u0651\u0642 \u0645\u0633\u062c\u0651\u0644 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0641\u062a\u062d \u0623\u064a \u062e\u062a\u0645 \u0642\u0628\u0644 \u0625\u0639\u062f\u0627\u062f\u0647."},
gAJ(){return"\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0639\u0627\u0645\u0644\u0643 \u0627\u0644\u062b\u0627\u0646\u064a \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u062d\u0627\u0644\u064a\u064b\u0627. \u0623\u0639\u062f \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0623\u0648 \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643."},
gAE(){return"\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u062b\u0627\u0646\u064a"},
gAG(){return"\u0647\u0644 \u0641\u0642\u062f\u062a \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629\u061f"},
gAD(){return"\u062a\u0623\u0643\u064a\u062f"},
gtA(){return"\u062a\u0645\u0651 \u0631\u0641\u0636 \u0627\u0644\u0631\u0645\u0632. \u064a\u062a\u063a\u064a\u0651\u0631 \u0643\u0644 30 \u062b\u0627\u0646\u064a\u0629 \u2014 \u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0639\u0631\u0648\u0636 \u0627\u0644\u0622\u0646."},
gAI(){return"\u064a\u062a\u0637\u0644\u0651\u0628 \u0641\u062a\u062d \u0627\u0644\u0623\u062e\u062a\u0627\u0645 \u0639\u0627\u0645\u0644\u064b\u0627 \u062b\u0627\u0646\u064a\u064b\u0627 \u062a\u0645\u0651 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646\u0647 \u0642\u0628\u0644 \u0623\u0642\u0644 \u0645\u0646 15 \u062f\u0642\u064a\u0642\u0629."},
gpG(){return"\u0639\u0627\u0645\u0644\u064a \u0627\u0644\u062b\u0627\u0646\u064a"},
grD(){return"\u0645\u0637\u0644\u0648\u0628 \u0644\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062d\u0633\u0651\u0627\u0633\u0629"},
gJJ(){return"\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0627\u0644\u0642\u0648\u064a \u0645\u064f\u0641\u0639\u0651\u0644 \u0644\u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629"},
gJK(){return"\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0627\u0644\u0642\u0648\u064a \u063a\u064a\u0631 \u0645\u064f\u0641\u0639\u0651\u0644 \u0644\u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629"},
JM(a){return"\u062a\u0645\u0651 \u0627\u0644\u062a\u062d\u0642\u0642 \u0641\u064a "+a},
gx7(){return"\u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u062b\u0627\u0646\u064a \u0641\u0639\u0651\u0627\u0644"},
gJr(){return"\u0644\u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628 \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d \u0645\u0648\u062b\u0651\u0642. \u064a\u064f\u0637\u0644\u0628 \u0631\u0645\u0632\u0647 \u0639\u0646\u062f \u0625\u062c\u0631\u0627\u0621 \u062d\u0633\u0651\u0627\u0633 \u2014 \u0641\u062a\u062d \u0627\u0644\u0623\u062d\u0631\u0627\u0632 \u0623\u0648 \u0627\u0644\u0645\u0631\u0627\u0642\u0628 \u0627\u0644\u062a\u0642\u0646\u064a."},
gJE(){return"\u0625\u0632\u0627\u0644\u0629 \u0647\u0630\u0627 \u0627\u0644\u0639\u0627\u0645\u0644"},
gJF(){return"\u063a\u064a\u0631 \u0645\u062a\u0627\u062d \u0647\u0646\u0627: \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u0645\u0648\u062b\u0651\u0642 \u0627\u0644\u0648\u062d\u064a\u062f \u0633\u062a\u063a\u0644\u0642 \u0641\u0648\u0631\u064b\u0627 \u0643\u0644 \u0627\u0644\u0623\u062e\u062a\u0627\u0645 \u0627\u0644\u062a\u064a \u064a\u0645\u0643\u0646\u0643 \u0641\u062a\u062d\u0647\u0627."},
gJC(){return"\u0625\u0639\u062f\u0627\u062f \u0644\u0645 \u064a\u064f\u0633\u062a\u0643\u0645\u0644"},
gJB(){return"\u062a\u0645\u0651 \u0625\u0646\u0634\u0627\u0621 \u0639\u0627\u0645\u0644 \u0644\u0643\u0646\u0651\u0647 \u0644\u0645 \u064a\u064f\u0648\u062b\u0651\u0642 \u0642\u0637\u0651. \u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0645\u0646 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0644\u0625\u0643\u0645\u0627\u0644\u0647\u060c \u0623\u0648 \u0623\u0632\u0644\u0647 \u0648\u0627\u0628\u062f\u0623 \u0645\u0646 \u062c\u062f\u064a\u062f."},
gJy(){return"\u0625\u0643\u0645\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f"},
gJD(){return"\u0625\u0632\u0627\u0644\u0629 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u063a\u064a\u0631 \u0627\u0644\u0645\u0643\u062a\u0645\u0644"},
gJG(){return"\u062a\u0645\u062a \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0639\u0627\u0645\u0644"},
gxa(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d"},
gJA(){return"\u0628\u062f\u0648\u0646 \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d\u060c \u064a\u0631\u0641\u0636 \u0627\u0644\u062e\u0627\u062f\u0645 \u0643\u0644 \u0642\u0631\u0627\u0631 \u0628\u0641\u062a\u062d \u0627\u0644\u0623\u062f\u0644\u0629 \u0627\u0644\u0645\u062e\u062a\u0648\u0645\u0629. \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u064a\u0633\u062a\u063a\u0631\u0642 \u062f\u0642\u064a\u0642\u0629 \u0648\u062a\u0637\u0628\u064a\u0642 \u0645\u0635\u0627\u062f\u0642\u0629."},
gJI(){return"\u0625\u0639\u062f\u0627\u062f \u062a\u0637\u0628\u064a\u0642 \u0645\u0635\u0627\u062f\u0642\u0629"},
gJx(){return"\u0623\u0636\u0641 \u0647\u0630\u0627 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0625\u0644\u0649 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0644\u062f\u064a\u0643"},
gJz(){return"\u0644\u0627 \u064a\u0639\u0631\u0636 \u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0631\u0645\u0632 QR: \u0627\u0646\u0633\u062e \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0623\u062f\u0646\u0627\u0647 \u0648\u0623\u0636\u0641\u0647 \u064a\u062f\u0648\u064a\u064b\u0627 \u0641\u064a \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 (Google Authenticator\u060c FreeOTP\u060c Authy\u2026)\u060c \u062b\u0645 \u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0643\u0648\u0651\u0646 \u0645\u0646 6 \u0623\u0631\u0642\u0627\u0645 \u0627\u0644\u0630\u064a \u064a\u0639\u0631\u0636\u0647."},
